#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static volatile int running = 1;

void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    running = 0;
}

int main()
{
    int result;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_2, PI_OUTPUT);

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Toggle GPIO pins
        gpioWrite(GPIO_PIN_1, 1);
        gpioWrite(GPIO_PIN_2, 0);
        printf("Setting GPIO %d HIGH, GPIO %d LOW\n", GPIO_PIN_1, GPIO_PIN_2);
        sleep(2);

        gpioWrite(GPIO_PIN_1, 0);
        gpioWrite(GPIO_PIN_2, 1);
        printf("Setting GPIO %d LOW, GPIO %d HIGH\n", GPIO_PIN_1, GPIO_PIN_2);
        sleep(2);
    }

    // Release GPIO pins before exiting
    gpioTerminate();
    printf("GPIO control stopped.\n");

    return 0;
}

