// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Timeout duration in microseconds
#define TIMEOUT_US 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to measure distance using HC-SR04 sensor
float getDistance()
{
    long startTime, endTime, pulseWidth;

    // Trigger the sensor
    gpioTrigger(TRIGGER_PIN, 10, 1);

    // Wait for the echo pin to go high (start of pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }
    startTime = gpioTick();

    // Wait for the echo pin to go low (end of pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }
    endTime = gpioTick();

    // Calculate pulse width in microseconds
    pulseWidth = endTime - startTime;

    // Calculate distance in centimeters
    float distance = (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

