// Constants
#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define ADS1115_ADDR_1 0x28   // I2C address of ADS1115 sensor 1
#define ADS1115_ADDR_2 0x29   // I2C address of ADS1115 sensor 2
#define CONFIG_REG 0x01       // Configuration register address
#define CONVERSION_REG 0x00    // Conversion register address
#define SAMPLE_RATE_HZ 1      // Sampling rate in Hz

// Global variables
volatile sig_atomic_t keep_running = 1;
int i2c_fd;

// Function prototypes
int ads1115_read_channel(int fd, int addr, int mux);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to read from ADS1115 channel
int ads1115_read_channel(int fd, int addr, int mux) {
    uint8_t config[3];
    uint8_t data[2];
    int16_t raw_value;
    int retries = 3; // Number of retries

    // Construct configuration register value
    config[0] = CONFIG_REG;
    config[1] = 0xC2 | ((mux & 0x07) << 4); // Single-shot mode, AIN0-AIN1, +/-4.096V, Disable comparator
    config[2] = 0x83;                       // Start single conversion, 128 SPS

    while (retries > 0) {
        if (write(fd, config, 3) != 3) {
            perror("Failed to write to I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(9000); // Wait for conversion (at least 8ms)

        // Read conversion register
        uint8_t reg = CONVERSION_REG;
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            retries--;
            usleep(10000);
            continue;
        }
        if (read(fd, data, 2) != 2) {
            perror("Failed to read from I2C device");
            retries--;
            usleep(10000);
            continue;
        }

        raw_value = (data[0] << 8) | data[1];

        // Check for valid range (+/-4.096V)
        if (raw_value >= -32768 && raw_value <= 32767) {
            return raw_value;
        } else {
            fprintf(stderr, "Invalid reading: %d\n", raw_value);
            return -1; // Indicate invalid reading
        }
    }

    fprintf(stderr, "Failed to read after multiple retries.\n");
    return -1; // Indicate failure
}

