    int sensor1_addr = ADS1115_ADDR_1;
    int sensor2_addr = ADS1115_ADDR_2;
    int sensor1_raw, sensor2_raw;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
