#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

// Configuration register values (Single-shot mode, AIN0, +/-4.096V, 128 SPS)
#define CONFIG_DEFAULT 0xC3F3 //0b1100001111110011

int i2c_fd;

// Function to write data to I2C device
int i2c_write(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from I2C device
int i2c_read(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    int16_t adc_value;
    uint16_t config_value = CONFIG_DEFAULT;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115 for single-shot conversion
    if (i2c_write(i2c_fd, CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for conversion to complete (adjust delay as needed based on sample rate)
    usleep(100000); // 100ms

    // Read ADC value
    if (i2c_read(i2c_fd, CONVERSION_REG, (uint16_t *)&adc_value) < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Print ADC value
    printf("ADC Value: %d\n", adc_value);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

