/*
 * Calculates the CRC checksum of the given 16-bit data.
 */
uint8_t calculate_checksum(uint16_t data) {
    uint8_t crc = 0;
    uint8_t data_bytes[2];
    data_bytes[0] = data >> 8;
    data_bytes[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
        crc ^= data_bytes[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc <<= 1;
        }
    }
    return crc;
}

