 * Reads the ADC value from the specified channel of the ADS1115.
 */
int ads1115_read_channel(int fd, int channel) {
    uint8_t config[3];
    int16_t raw_adc;
    uint8_t msb, lsb;

    // Configure ADS1115 for single-ended mode, AIN0-AIN1, +/-4.096V, 128 SPS, start single conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC2 | ((channel & 0x03) << 4); // Single-ended, channel selection
    config[2] = 0xE3; // 128 SPS, +/-4.096V, start single conversion

    // Write configuration to the ADS1115
    if (write(fd, config, 3) != 3) {
        perror("Error: Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    uint8_t reg = CONVERSION_REG;
    if (write(fd, &reg, 1) != 1) {
        perror("Error: Failed to write to I2C device");
        return -1;
    }

    if (read(fd, &lsb, 1) != 1 || read(fd, &msb, 1) != 1) {
        perror("Error: Failed to read from I2C device");
        return -1;
    }

    raw_adc = (msb << 8) | lsb;

    return raw_adc;
}

