#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B9600

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int uart_fd;
    struct termios tty;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    // Open the UART port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", UART_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    // Configure the UART
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("tcgetattr failed");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);//Enable receiver and set local mode
    tty.c_cflag &= ~CSIZE;      /* Mask the character size bits */
    tty.c_cflag |= CS8;       /* 8-bit data */
    tty.c_cflag &= ~(PARENB | PARODD); /* No parity */
    tty.c_cflag &= ~CSTOPB;     /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;    /* Disable RTS/CTS hardware flow control */

    tty.c_iflag &= ~IGNBRK;         /* disable break processing */
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);  // shut off xon/xoff ctrl

    tty.c_lflag = 0;                /* no signaling chars, no echo, no canonical processing */
    tty.c_oflag = 0;                /* no remapping, no delays */

    tty.c_cc[VMIN]  = 0;            /* read doesn't block */
    tty.c_cc[VTIME] = 5;            /* 0.5 seconds read timeout */

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    char buffer[256];
    ssize_t bytes_read;

    printf("Reading from UART %s at %d baud...\n", UART_PORT, BAUD_RATE);

    while (keep_running) {
        memset(buffer, 0, sizeof(buffer)); // Clear the buffer before each read
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            perror("Read error");
            break; // Exit loop on error
        } else {
            // Timeout occurred or no data available
            usleep(100000); // Sleep for 100ms to avoid busy-waiting
        }
    }

    // Close the UART port
    close(uart_fd);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

