// Function to read data from DHT11 sensor
int read_dht11_data(float *temperature, float *humidity) {
    int i, bit_count = 0;
    unsigned int data[5] = {0, 0, 0, 0, 0};

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18); // > 1ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20us

    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for response (low then high)
    int timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1 && timeout++ < 100) {
        gpioDelay(1); // Check every microsecond
    }
    if (timeout >= 100) return -1; // Timeout waiting for low

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 0 && timeout++ < 100) {
        gpioDelay(1);
    }
    if (timeout >= 100) return -1; // Timeout waiting for high

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1 && timeout++ < 100) {
        gpioDelay(1);
    }
    if (timeout >= 100) return -1; // Timeout waiting for low

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0 && timeout++ < 100) {
            gpioDelay(1);
        }
        if (timeout >= 100) return -1; // Timeout waiting for high

        long start = time_time();
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1 && timeout++ < 100) {
            gpioDelay(1);
        }
        if (timeout >= 100) return -1; // Timeout waiting for low

        long end = time_time();

        if ((end - start) > 30) { // Determine if it's a '1' or '0'
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        fprintf(stderr, "Checksum failure!\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)data[0];
    *temperature = (float)(data[2] & 0x7F); // Mask out sign bit

    return 0;
}

