    if ((fd = open (buf, O_WRONLY)) < 0)
    {
      fprintf (stderr, "Unable to open GPIO value for writing: %s\n", strerror (errno)) ;
      return 1 ;
    }
    printf ("Writing HIGH...\n") ; fflush (stdout) ;
    write (fd, "1", 1) ;
    close (fd) ;
    delayMicroseconds (10000) ;

    sprintf (buf, "%d/value", sysfsRoot) ;
    if ((fd = open (buf, O_WRONLY)) < 0)
    {
