#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

// Define the I2C device file and address
#define I2C_DEVICE "/dev/i2c-1"
#define OPT3001_ADDRESS 0x44

int main() {
    int i2c_fd;
    uint8_t config_reg[2] = {0x01, 0xC0}; // Configuration register value: Continuous mode, Range auto
    uint8_t result_buffer[2];
    unsigned int raw_result;

    // Open the I2C device file
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return EXIT_FAILURE;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure the OPT3001
    if (write(i2c_fd, config_reg, sizeof(config_reg)) != sizeof(config_reg)) {
        perror("Error writing to configuration register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read the result register
    uint8_t read_command[1] = {0x00}; // Result register address
    if (write(i2c_fd, read_command, sizeof(read_command)) != sizeof(read_command)) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (read(i2c_fd, result_buffer, sizeof(result_buffer)) != sizeof(result_buffer)) {
        perror("Error reading from I2C device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Combine the two bytes into a single unsigned integer
    raw_result = (result_buffer[0] << 8) | result_buffer[1];

    // Extract exponent and result values
    int exponent = (raw_result >> 12) & 0x0F;
    unsigned int result = raw_result & 0x0FFF;

    // Calculate the lux value
    float lux = result * (0.01 * (1 << exponent));

    // Print the lux value
    printf("Lux: %.2f\n", lux);

    // Close the I2C device file
    close(i2c_fd);

    return EXIT_SUCCESS;
}

