// Function to discover the DS18B20 device ID
int discover_device_id(char *device_id)
{
    DIR *dir;
    struct dirent *entry;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_DIR);
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            strncpy(device_id, entry->d_name, MAX_DEVICE_ID_LENGTH - 1);
            closedir(dir);
            return 0; // Success
        }
    }

    closedir(dir);
    return -1; // Device not found
}

// Function to read the temperature from the sensor
float read_temperature(const char *device_id)
{
    char filepath[64];
    int fd;
    char buffer[16];
    ssize_t bytes_read;
    float temperature = -999.0; // Default invalid value

    snprintf(filepath, sizeof(filepath), "%s%s/w1_slave", W1_DEVICES_DIR, device_id);

    fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("Error opening w1_slave file");
        return -999.0;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';

        // Check for CRC error
        if (strstr(buffer, "YES") != NULL) {
            char *temp_str = strstr(buffer, "t=");
            if (temp_str != NULL) {
                long temp_value = strtol(temp_str + 2, NULL, 10);
                temperature = (float)temp_value / 1000.0;
            } else {
                fprintf(stderr, "Temperature data format error\n");
            }
        } else {
            fprintf(stderr, "CRC check failed\n");
        }
    } else {
        fprintf(stderr, "Error reading w1_slave file\n");
    }

    return temperature;
}

// Function to validate the temperature reading
int validate_temperature(float temperature)
{
    if (temperature >= -50.0 && temperature <= 125.0) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Invalid temperature: %.2f\n", temperature);
        return -1; // Invalid
    }
}

// Function to print the temperature with a timestamp
void print_temperature(float temperature)
{
    time_t now = time(NULL);
    printf("%ld: Temperature: %.2f °C\n", now, temperature);
}

int main()
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Discover the device ID
    if (discover_device_id(device_id) != 0) {
        fprintf(stderr, "DS18B20 device not found\n");
        return EXIT_FAILURE;
    }

    printf("Found DS18B20 device with ID: %s\n", device_id);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(device_id);

        if (temperature != -999.0) {
            if (validate_temperature(temperature) == 0) {
                print_temperature(temperature);
            }
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define MEASURE_CMD 0xE3 // High Repeatability Measurement Command

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus);
int htu21d_read_temperature(int fd, float *temperature);
void signal_handler(int sig);

/*
 * Signal handler to gracefully close the I2C connection.
 */
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

/*
 * Initializes the I2C bus.
 */
int i2c_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Reads temperature data from the HTU21D sensor.
 */
int htu21d_read_temperature(int fd, float *temperature) {
    uint8_t buf[3];
    unsigned int raw_temp;
    float temp_celsius;

    // Send measurement command
    if (write(fd, &MEASURE_CMD, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

usleep(50000); // Wait for conversion (at least 50ms)

    // Read 3 bytes of data
    if (read(fd, buf, 3) != 3) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert raw data to temperature
    raw_temp = ((uint32_t)buf[0] << 8) | buf[1];

    // Apply formula from datasheet
    temp_celsius = -46.85 + 175.72 * ((float)raw_temp / 65536.0);

    // Validate temperature range
    if (temp_celsius < -40.0 || temp_celsius > 125.0) {
        fprintf(stderr, "Invalid temperature reading: %.2f\n", temp_celsius);
        return -1;
    }

    *temperature = temp_celsius;
    return 0;
}

int main() {
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        if (htu21d_read_temperature(i2c_fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 60 seconds.\n");
        }

        sleep(60);
    }

    // Cleanup
    close(i2c_fd);
    printf("I2C connection closed. Exiting.\n");

    return EXIT_SUCCESS;
}

