}

// Function to load configuration from file
int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key && value) {
            if (strcmp(key, "dht22_gpio") == 0) {
                config->dht22_gpio = atoi(value);
            } else if (strcmp(key, "mq_name") == 0) {
                strncpy(config->mq_name, value, sizeof(config->mq_name) - 1);
                config->mq_name[sizeof(config->mq_name) - 1] = '\0';
            } else if (strcmp(key, "max_temp") == 0) {
                config->max_temp = atof(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to read data from DHT22 sensor
int read_dht22_data(int gpio_pin, float *temperature, float *humidity) {
    int result;
    int i;
    unsigned int data[5] = {0, 0, 0, 0, 0};

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30);

    gpioSetMode(gpio_pin, PI_INPUT);

    unsigned int tick = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - tick > 100) return -1;
    }

    tick = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - tick > 100) return -1;
    }

    tick = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - tick > 100) return -1;
    }

    for (i = 0; i < 40; i++) {
        tick = gpioTick();
        while (gpioRead(gpio_pin) == 0) {
            if (gpioTick() - tick > 100) return -1;
        }

        unsigned int t = gpioTick();
        while (gpioRead(gpio_pin) == 1) {
            if (gpioTick() - t > 100) return -1;
        }

        if ((gpioTick() - t) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)((((data[2] & 0x7F) << 8) | data[3])) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

// Function to format data into JSON string
char* format_json(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char json_string[256]; // Static to avoid stack allocation issues

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"temperature\": %.2f, \"humidity\": %.2f}", timestamp, temperature, humidity);
    return json_string;
}

// Function to send message to message queue
int send_message(mqd_t mq, const char *message) {
    if (mq_send(mq, message, strlen(message), 0) == -1) {
        perror("mq_send failed");
        return -1;
    }
    return 0;
}

int main() {
    // Load configuration
    if (load_config("config.txt", &config) != 0) {
        fprintf(stderr, "Failed to load configuration. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open message queue
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = 256;
    attr.mq_curmsgs = 0;

    mq = mq_open(config.mq_name, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    float temperature, humidity;
    while (!terminate) {
        if (read_dht22_data(config.dht22_gpio, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

            char *json_data = format_json(temperature, humidity);

            if (send_message(mq, json_data) != 0) {
                fprintf(stderr, "Failed to send message to queue.\n");
            }

            if (temperature > config.max_temp) {
                fprintf(stderr, "WARNING: Temperature exceeds maximum threshold!\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data.\n");
        }

        sleep(2);
    }

    // Cleanup
    mq_close(mq);
    mq_unlink(config.mq_name);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

