// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_WTIME           0x03
#define TCS34725_AILTL           0x04
#define TCS34725_AILTH           0x05
#define TCS34725_AIHTL           0x06
#define TCS34725_AIHTH           0x07
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// Enable Register Values
#define TCS34725_PON             0x01
#define TCS34725_AEN             0x02

// Integration Time Value
#define TCS34725_INTEGRATIONTIME_2_4MS   0xFF   //  2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS    0xF6   //  24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS    0xEB   //  50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS   0xD5   //  101ms - 42 cycles   - Max Count: 42592
#define TCS34725_INTEGRATIONTIME_154MS   0xC0   //  154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_238MS   0xA0   //  238ms - 98 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_1_35S   0x00   //  1.35s - 256 cycles  - Max Count: 65535


static int i2c_fd = -1;
volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        keep_running = 0;
    }
}

int tcs34725_init() {
    uint8_t id;
    uint8_t enable;

    // Check ID register
    if (i2c_smbus_read_byte_data(i2c_fd, TCS34725_ID | TCS34725_COMMAND_BIT) != 0x44) {
        fprintf(stderr, "Error: Invalid TCS34725 ID\n");
        return -1;
    }

    // Set integration time
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ATIME | TCS34725_COMMAND_BIT, TCS34725_INTEGRATIONTIME_24MS) < 0) {
        perror("Failed to set integration time");
        return -1;
    }

    // Enable power and ALS
    enable = TCS34725_PON | TCS34725_AEN;
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ENABLE | TCS34725_COMMAND_BIT, enable) < 0) {
        perror("Failed to enable sensor");
        return -1;
    }

    return 0;
}

int read_raw_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t data[8];

    // Read all color data in one go
    if (i2c_smbus_read_i2c_block_data(i2c_fd, TCS34725_CDATA | TCS34725_COMMAND_BIT, 8, (char *)data) < 0) {
        perror("Failed to read color data");
        return -1;
    }

    *clear   = (uint16_t)data[1] << 8 | data[0];
    *red     = (uint16_t)data[3] << 8 | data[2];
    *green   = (uint16_t)data[5] << 8 | data[4];
    *blue    = (uint16_t)data[7] << 8 | data[6];

    return 0;
}

int main() {
    struct timespec sleep_time = {0, 200000000}; // 0.2 seconds
    uint16_t red, green, blue, clear;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

