    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized successfully.\n");

    while (keep_running) {
        if (read_raw_data(&red, &green, &blue, &clear) == 0) {
            printf("%u,%u,%u,%u\n", red, green, blue, clear);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Disable sensor before exiting
    uint8_t disable = 0; // Disable PON and AEN
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ENABLE | TCS34725_COMMAND_BIT, disable) < 0) {
        perror("Failed to disable sensor");
    }

    close(i2c_fd);
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

