// Define the GPIO pins to be used as outputs
const int gpio_pins[] = {1, 4, 5, 6, 21, 22, 23, 24};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Release the GPIO pins before exiting
    for (int i = 0; i < num_pins; ++i)
    {
        gpioSetMode(gpio_pins[i], PI_INPUT); // Set back to input mode
    }
    gpioTerminate(); // Terminate the pigpio library
    exit(0);         // Exit the program
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Configure each GPIO pin as an output
    for (int i = 0; i < num_pins; ++i)
    {
        gpioSetMode(gpio_pins[i], PI_OUTPUT);
    }

    // Apply HIGH voltage to each GPIO pin
    for (int i = 0; i < num_pins; ++i)
    {
        gpioWrite(gpio_pins[i], 1);
