#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480

struct buffer {
    void   *start;
    size_t  length;
};

int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main()
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    char filename[32];
    FILE *fp;
    int fd;
    struct buffer *buffers;
    unsigned int n_buffers;
    enum v4l2_buf_type type;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Check device capabilities
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)){
            perror("VIDIOC_QUERYBUF");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL /* start anywhere */,
                                       buf.length,
                                       PROT_READ | PROT_WRITE /* required */,
                                       MAP_SHARED /* recommended */,
                                       fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    // Queue the buffers
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)){
            perror("VIDIOC_QBUF");
            close(fd);
            munmap(buffers[i].start, buffers[i].length);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)){
        perror("VIDIOC_STREAMON");
        close(fd);
        munmap(buffers[i].start, buffers[i].length);
        free(buffers);
        return EXIT_FAILURE;
    }

    // Capture images in a loop
    for (;;) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)){
            perror("VIDIOC_DQBUF");
            break; // Exit loop on error
        }

        // Generate a unique filename based on timestamp
        snprintf(filename, sizeof(filename), "image_%ld.jpg", time(NULL));

        // Open the file for writing
        fp = fopen(filename, "wb");
        if (!fp) {
            perror("Failed to open file for writing");
            break; // Exit loop on error
        }

        // Write the image data to the file
        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);

        // Close the file
        fclose(fp);

        printf("Captured image saved as %s\n", filename);

        // Requeue the buffer
        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)){
            perror("VIDIOC_QBUF");
            break; // Exit loop on error
        }

        usleep(50000); // Sleep for 0.05 seconds
    }

    // Stop streaming
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)){
        perror("VIDIOC_STREAMOFF");
    }

    // Unmap the buffers
    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)){
            perror("munmap");
        }
    }

    // Free the buffers array
    free(buffers);

    // Close the device
    close(fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold calibration data
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    uint8_t dig_H6;
};

struct bme280_calib_data calib;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read byte");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// Function to initialize the BME280 sensor
int bme280_init(int fd) {
    // Check the chip ID
    uint8_t chip_id;
    if (i2c_read_byte(fd, BME280_REG_ID, &chip_id) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    uint8_t buffer[26];
    uint8_t hum_buffer[7];

    if (i2c_read_byte(fd, BME280_REG_CALIB_00, &buffer[0]) != 0) return -1;
    if (i2c_read_byte(fd, 0xE1, &hum_buffer[0]) != 0) return -1;

    calib.dig_T1 = (uint16_t)(buffer[1] << 8 | buffer[0]);
    calib.dig_T2 = (int16_t)(buffer[3] << 8 | buffer[2]);
    calib.dig_T3 = (int16_t)(buffer[5] << 8 | buffer[4]);
    calib.dig_P1 = (uint16_t)(buffer[7] << 8 | buffer[6]);
    calib.dig_P2 = (int16_t)(buffer[9] << 8 | buffer[8]);
    calib.dig_P3 = (int16_t)(buffer[11] << 8 | buffer[10]);
    calib.dig_P4 = (int16_t)(buffer[13] << 8 | buffer[12]);
    calib.dig_P5 = (int16_t)(buffer[15] << 8 | buffer[14]);
    calib.dig_P6 = (int16_t)(buffer[17] << 8 | buffer[16]);
    calib.dig_P7 = (int16_t)(buffer[19] << 8 | buffer[18]);
    calib.dig_P8 = (int16_t)(buffer[21] << 8 | buffer[20]);
    calib.dig_P9 = (int16_t)(buffer[23] << 8 | buffer[22]);
    calib.dig_H1 = buffer[25];
    calib.dig_H2 = (int16_t)(hum_buffer[1] << 8 | hum_buffer[0]);
    calib.dig_H3 = hum_buffer[2];
    calib.dig_H4 = (int16_t)((hum_buffer[3] << 4) | (hum_buffer[4] & 0x0F));
    calib.dig_H5 = (int16_t)((hum_buffer[5] << 4) | (hum_buffer[4] >> 4));
    calib.dig_H6 = hum_buffer[6];

    // Set humidity control register
    if (i2c_write_byte(fd, BME280_REG_CTRL_HUM, 0x01) != 0) return -1; // Humidity oversampling x1

    // Set control measurement register
    if (i2c_write_byte(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) return -1; // Temperature and pressure oversampling x1, normal mode

    // Set config register
    if (i2c_write_byte(fd, BME280_REG_CONFIG, 0x00) != 0) return -1; // t_sb = 0.5ms, filter off

    return 0;
}

// Function to read raw temperature, pressure, and humidity values
int bme280_read_raw(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t data[8];

    // Read pressure MSB, LSB, XLSB
    uint8_t reg_addr = BME280_REG_PRESSURE_MSB;
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 6) != 6) {
        perror("Failed to read pressure data");
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)data[0]) << 12) | (((uint32_t)data[1]) << 4) | ((uint32_t)data[2] >> 4));

    // Read temperature MSB, LSB, XLSB
    reg_addr = BME280_REG_TEMP_MSB;
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 6) != 6) {
        perror("Failed to read temperature data");
        return -1;
    }

    *temperature = (int32_t)((((uint32_t)data[0]) << 12) | (((uint32_t)data[1]) << 4) | ((uint32_t)data[2] >> 4));

    // Read humidity MSB, LSB
    reg_addr = BME280_REG_HUMIDITY_MSB;
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read humidity data");
        return -1;
    }

    *humidity = (int32_t)(((uint32_t)data[0]) << 8 | (uint32_t)data[1]);

    return 0;
}

// Function to compensate temperature value
float bme280_compensate_temperature(int32_t adc_T, struct bme280_calib_data cal) {
    double var1, var2, T;
    static double t_fine;

    var1 = (((double)adc_T)/16384.0 - ((double)cal.dig_T1)/1024.0) * ((double)cal.dig_T2);
    var2 = ((((double)adc_T)/131072.0 - ((double)cal.dig_T1)/8192.0) * (((double)adc_T)/131072.0 - ((double)cal.dig_T1)/8192.0)) * ((double)cal.dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return (float)T;
}

// Function to compensate pressure value
float bme280_compensate_pressure(int32_t adc_P, struct bme280_calib_data cal) {
    double var1, var2, p;
    double t_fine = 0; // Assuming t_fine is available from temperature compensation

    var1 = ((double)t_fine/2.0) - 64000.0;
    var2 = var1 * var1 * ((double)cal.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)cal.dig_P5) * 2.0;
    var2 = (var2/4.0)+(((double)cal.dig_P4) * 65536.0);
