/*
 * Reads the specified analog input channel from the ADS1115.
 *
 * @param fd: File descriptor for the I2C device.
 * @param mux: MUX configuration value (e.g., 0x4000 for AIN0-GND).
 * @return: The 16-bit ADC reading, or -1 on error.
 */
int ads1115_read_channel(int fd, int mux) {
    uint8_t config[3];
    int16_t raw_value;

    // Configure the ADS1115 for single-shot mode, +/-4.096V range,
    // and the specified channel.
    config[0] = CONFIG_REG;
    config[1] = (mux >> 8) & 0xFF; // MSB of the mux value
    config[2] = mux & 0xFF;      // LSB of the mux value

    // Write the configuration to the ADS1115
    if (write(fd, config, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms)
    usleep(10000); // 10 ms

    // Read the conversion result
    uint8_t read_buffer[2];
    lseek(fd, CONVERSION_REG, SEEK_SET); // Set file pointer to conversion register
    if (read(fd, read_buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two bytes into a signed 16-bit integer
    raw_value = (read_buffer[0] << 8) | read_buffer[1];

    return raw_value;
}

