// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Ensure CS is initially high

    return 0;
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                  // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                  // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Open SPI channel at 1MHz
    if(spi_handle < 0){
      fprintf(stderr, "SPI open failed\n");
      gpioWrite(MCP3008_CS, 1);
      return -1;
    }

    spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    spiClose(spi_handle);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    float voltage = (adc_value / 1023.0) * 3.3;
    return voltage;
}

// Function to format data as JSON string
char* format_json(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    static char json_string[256]; // Static buffer to avoid stack allocation issues
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"voltage\": %.3f}", timestamp, voltage);

    return json_string;
}

// Function to publish data to MQTT broker
int publish_data(const char *json_string) {
    int ret = mosquitto_publish(mosq, NULL, config.topic, strlen(json_string), json_string, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration from file
    if (read_config(&config) != 0) {
        fprintf(stderr, "Failed to read configuration. Using default values.\n");
        strcpy(config.mqtt_broker, DEFAULT_MQTT_BROKER);
        config.mqtt_port = DEFAULT_MQTT_PORT;
        strcpy(config.client_id, DEFAULT_SENSOR_ID);
        strcpy(config.username, ""); // Empty username
        strcpy(config.password, ""); // Empty password
        strcpy(config.topic, "environmental/sensor/data"); // Default topic
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(config.client_id, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Set username and password if provided in config
    if(strlen(config.username) > 0 && strlen(config.password) > 0){
        mosquitto_username_pw_set(mosq, config.username, config.password);
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, config.mqtt_broker, config.mqtt_port, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor data
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert to voltage
