// Include I2C library
#include <pigpio.h>

// Include MQTT client library
#include <MQTTClient.h>

// Configuration parameters
#define CONFIG_FILE "config.ini"
#define DEFAULT_I2C_ADDRESS 0x48
#define DEFAULT_MQTT_BROKER "localhost"
#define DEFAULT_MQTT_PORT 1883
#define DEFAULT_MQTT_TOPIC "agriculture/sensor_data"

// ADS1115 Registers
#define ADS1115_REG_CONFIG   0x01
#define ADS1115_REG_CONVERT  0x00

// ADS1115 Configuration Values
#define ADS1115_CONFIG_OS_SINGLE      0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_DIFF_0_1   0x0000  // Differential P = AIN0, N = GND
#define ADS1115_CONFIG_PGA_4_096V     0x0200  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE    0x0100  // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS       0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD  0x0000  // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_ACTIVE_LOW 0x0000 // Active low comparator polarity
#define ADS1115_CONFIG_COMP_LAT_NON_LATCHING 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE  0x0003  // Disable comparator

// Global variables
static int i2c_handle;
static int ads1115_address = DEFAULT_I2C_ADDRESS;
static char *mqtt_broker = NULL;
static int mqtt_port = DEFAULT_MQTT_PORT;
static char *mqtt_topic = NULL;
static MQTTClient client;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename);
int initialize_i2c(int address);
int read_ads1115(float *value);
int publish_mqtt(MQTTClient client, const char *topic, float value);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nReceived signal %d, terminating...\n", signum);
        terminate = 1;
    }
}

// Read configuration from file
int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "i2c_address") == 0) {
                ads1115_address = strtol(value, NULL, 16);
            } else if (strcmp(key, "mqtt_broker") == 0) {
                mqtt_broker = strdup(value);
            } else if (strcmp(key, "mqtt_port") == 0) {
                mqtt_port = atoi(value);
            } else if (strcmp(key, "mqtt_topic") == 0) {
                mqtt_topic = strdup(value);
            }
        }
    }

    fclose(fp);

    if (mqtt_broker == NULL) {
        mqtt_broker = strdup(DEFAULT_MQTT_BROKER);
    }
    if (mqtt_topic == NULL) {
        mqtt_topic = strdup(DEFAULT_MQTT_TOPIC);
    }

    printf("Configuration:\n");
    printf("  I2C Address: 0x%02X\n", ads1115_address);
    printf("  MQTT Broker: %s\n", mqtt_broker);
    printf("  MQTT Port: %d\n", mqtt_port);
    printf("  MQTT Topic: %s\n", mqtt_topic);

    return 0;
}

// Initialize I2C communication
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(float *value) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_DIFF_0_1 | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_ACTIVE_LOW | ADS1115_CONFIG_COMP_LAT_NON_LATCHING |
                      ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Write configuration register
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG >> 8;
    buf[1] = ADS1115_REG_CONFIG & 0xFF;
    buf[2] = config >> 8;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    // Read conversion register
    buf[0] = ADS1115_REG_CONVERT >> 8;
    buf[1] = ADS1115_REG_CONVERT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];

    // Convert to voltage (assuming +/-4.096V range)
    *value = (float)raw_value * 4.096 / 32768.0;

    return 0;
}

// Publish data to MQTT broker
int publish_mqtt(MQTTClient client, const char *topic, float value) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    char payload[50];
    snprintf(payload, sizeof(payload), "%.3f", value);

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = QOS0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Failed to read configuration, exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (initialize_i2c(ads1115_address) != 0) {
        fprintf(stderr, "I2C initialization failed, exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize MQTT client
    int rc = MQTTClient_create(&client, mqtt_broker, "raspberry_pi_sensor", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect, return code %d\n", rc);
        MQTTClient_destroy(&client);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker\n");

    // Main loop
    float sensor_value;
    for (int i = 0; i < 10 && !terminate; ++i) {
        if (read_ads1115(&sensor_value) == 0) {
            printf("Sensor Reading %d: %.3f V\n", i + 1, sensor_value);
            if (publish_mqtt(client, mqtt_topic, sensor_value) != 0) {
                fprintf(stderr, "Failed to publish reading %d\n", i + 1);
            }
        } else {
            fprintf(stderr, "Failed to read sensor value %d\n", i + 1);
        }
        sleep(1);
    }

    // Disconnect from MQTT broker
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Free allocated memory
    free(mqtt_broker);
    free(mqtt_topic);

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

