        result = gpioWrite(GPIO_17, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_17, result);
        } else {
            printf("GPIO %d set HIGH\n", GPIO_17);
        }
        usleep(25000); // 0.025 seconds

        // Toggle GPIO 18
        result = gpioWrite(GPIO_18, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_18, result);
        } else {
            printf("GPIO %d set HIGH\n", GPIO_18);
        }
        usleep(25000); // 0.025 seconds

        // Reset GPIO 17
        result = gpioWrite(GPIO_17, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_17, result);
        } else {
            printf("GPIO %d set LOW\n", GPIO_17);
        }
        usleep(25000); // 0.025 seconds

        // Reset GPIO 18
        result = gpioWrite(GPIO_18, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_18, result);
        } else {
            printf("GPIO %d set LOW\n", GPIO_18);
        }
        usleep(25000); // 0.025 seconds
    }

    // Release GPIOs before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");

    return 0;
}

