// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR_1 0x68
#define MPU6050_ADDR_2 0x69
#define ACCEL_XOUT_H 0x3B

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int open_i2c_bus(const char *bus);
int detect_mpu6050(int fd, uint8_t addr);
int read_acceleration(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z);
void signal_handler(int signum);

/*
 * Opens the I2C bus.
 */
int open_i2c_bus(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

/*
 * Detects the MPU6050 sensor at the given I2C address.
 */
int detect_mpu6050(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X\n", addr);
        return -1;
    }

    // Read WHO_AM_I register (0x75). Expected value is 0x68.
    uint8_t who_am_i_reg = 0x75;
    if (write(fd, &who_am_i_reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    uint8_t who_am_i_value;
    if (read(fd, &who_am_i_value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    if (who_am_i_value != 0x68) {
        fprintf(stderr, "Error: MPU6050 not found at address 0x%02X (WHO_AM_I=0x%02X)\n", addr, who_am_i_value);
        return -1;
    }

    printf("MPU6050 detected at address 0x%02X\n", addr);
    return 0;
}

/*
 * Reads acceleration data from the MPU6050.
 */
int read_acceleration(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t reg = ACCEL_XOUT_H;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    *accel_x = (buffer[0] << 8) | buffer[1];
    *accel_y = (buffer[2] << 8) | buffer[3];
    *accel_z = (buffer[4] << 8) | buffer[5];

    return 0;
}

/*
 * Prints the acceleration data to stdout.
 */
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    printf("%d,%d,%d\n", accel_x, accel_y, accel_z);
}

/*
 * Signal handler for graceful shutdown.
 */
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nReceived signal %d, exiting gracefully...\n", signum);
        stop_flag = 1;
    }
}

int main() {
    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = 0;
if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
perror("sigaction");
exit(EXIT_FAILURE);
}

    // Open I2C bus
    i2c_fd = open_i2c_bus(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Detect MPU6050 sensors
    uint8_t mpu6050_address[] = {MPU6050_ADDR_1, MPU6050_ADDR_2};
    int mpu6050_found = 0;
    for (int i = 0; i < sizeof(mpu6050_address) / sizeof(mpu6050_address[0]); ++i) {
        if (detect_mpu6050(i2c_fd, mpu6050_address[i]) == 0) {
            mpu6050_found = 1;
        }
    }

    if (!mpu6050_found) {
        fprintf(stderr, "Error: No MPU6050 sensors found. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z;
    while (!stop_flag) {
        for (int i = 0; i < sizeof(mpu6050_address) / sizeof(mpu6050_address[0]); ++i) {
            if (detect_mpu6050(i2c_fd, mpu6050_address[i]) == 0) {
                if (read_acceleration(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
                    print_data(accel_x, accel_y, accel_z);
                } else {
                    fprintf(stderr, "Error reading acceleration data from MPU6050 at address 0x%02X\n", mpu6050_address[i]);
                }
            }
        }
        usleep(100000); // 0.1 seconds
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

