    calib->dig_P7 = (int16_t)(buffer[18] | (buffer[19] << 8));
    calib->dig_P8 = (int16_t)(buffer[20] | (buffer[21] << 8));
    calib->dig_P9 = (int16_t)(buffer[22] | (buffer[23] << 8));

    return 0;
