// Function to initialize the BMP280 sensor
int init_bmp280(int fd, int addr) {
    // Check if the device is present by reading the chip ID
    uint8_t chip_id;
    if (read_reg(fd, BMP280_CHIP_ID_REG, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID from address 0x%02X\n", addr);
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID (0x%02X) from address 0x%02X. Expected 0x58.\n", chip_id, addr);
        return -1;
    }

    // Set oversampling rates and power mode
    uint8_t config = (0x02 << 5) | (0x05 << 2) | 0x03; // t_sb=0.5ms, filter=x16, normal mode
    if (write_reg(fd, BMP280_REG_CONFIG, &config, 1) != 1) {
        fprintf(stderr, "Error writing config register to address 0x%02X\n", addr);
        return -1;
    }

    uint8_t ctrl_meas = (0x02 << 5) | (0x02 << 2) | 0x03; // osrs_t=x16, osrs_p=x16, normal mode
    if (write_reg(fd, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Error writing control register to address 0x%02X\n", addr);
        return -1;
    }

    return 0;
}

// Function to write a single byte to a register
int write_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);

    ssize_t bytes_written = write(fd, buf, len + 1);
    if (bytes_written != len + 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from a register
int read_reg(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        perror("I2C read failed");
        return -1;
    }
    return len;
}

// Function to read temperature and pressure data
int read_temperature_pressure(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    if (read_reg(fd, BMP280_REG_PRESSURE_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading temperature/pressure data\n");
        return -1;
    }

    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    // Dummy implementation of compensation calculations.
    // Replace with actual BMP280 compensation formulas.
    *temperature = (float)raw_temperature / 100.0f;
    *pressure = (float)raw_pressure / 100.0f;

    return 0;
}

