// Function to initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n",
           (cap.version >> 16) & 0xFF,
           (cap.version >> 8) & 0xFF,
           cap.version & 0xFF);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        return -1;
    }
    return 0;
}

// Function to set the image format
int set_format(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Verify the format was set correctly
    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        perror("VIDIOC_G_FMT");
        return -1;
    }

    printf("Format: %c%c%c%c (%ux%u)\n",
           fmt.fmt.pix.pixelformat & 0xFF,
           (fmt.fmt.pix.pixelformat >> 8) & 0xFF,
           (fmt.fmt.pix.pixelformat >> 16) & 0xFF,
           (fmt.fmt.pix.pixelformat >> 24) & 0xFF,
           fmt.fmt.pix.width, fmt.fmt.pix.height);

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Function to read the frame data
int read_frame(int fd, unsigned char **buffer, size_t *size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *buffer = malloc(buf.bytesused);
    if (*buffer == NULL) {
        perror("malloc");
        return -1;
    }
    *size = buf.bytesused;

    int bytes_read = read(fd, *buffer, buf.bytesused);
    if (bytes_read != buf.bytesused) {
        fprintf(stderr, "Error reading frame: expected %zu bytes, got %d\n", buf.bytesused, bytes_read);
        free(*buffer);
        *buffer = NULL;
        *size = 0;
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        free(*buffer);
        *buffer = NULL;
        *size = 0;
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image(const char *filename, const unsigned char *image_data, size_t image_size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    size_t bytes_written = fwrite(image_data, 1, image_size, fp);
    if (bytes_written != image_size) {
        fprintf(stderr, "Error writing to file: expected %zu bytes, wrote %zu\n", image_size, bytes_written);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        fprintf(stderr, "Device %s not found or cannot be accessed.\n", DEVICE_NAME);
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (set_format(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_capturing(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *image_data = NULL;
    size_t image_size = 0;

    if (read_frame(fd, &image_data, &image_size) == -1) {
        stop_capturing(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    if (save_image(IMAGE_FILE, image_data, image_size) == -1) {
        free(image_data);
        stop_capturing(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Image saved as %s\n", IMAGE_FILE);

