// Function to read data from DHT22 sensor
int read_dht22_data(float *temperature, float *humidity)
{
    int i;
    unsigned int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for response (low then high)
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100us
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100us
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100us
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for low
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100us
        }

        // Measure duration of high pulse
        long start = time_time();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100us
        }
        long end = time_time();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        fprintf(stderr, "Checksum failure\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)((((data[2] & 0x7F) << 8) | data[3])) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

