#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        fprintf(stderr, "Check if %s exists and you have permissions.\n", DEVICE_NAME);
        return 1;
    }

    // Check if the device supports V4L2
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set the image format to JPEG
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.jpeg.compression_quality = 85; // Adjust quality as needed

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Capture a single frame
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;

    // Allocate memory for the buffer.  This example assumes a fixed size.
    // In a real application, you would need to determine the required buffer size
    // based on the camera's resolution and format.
    buffer_size = 640 * 480 * 3; // Example: 640x480 RGB24
    buffer = (unsigned char *)malloc(buffer_size);

    if (!buffer) {
        perror("Failed to allocate buffer");
        close(fd);
        return 1;
    }

    // Read the frame into the buffer
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Error reading frame");
        free(buffer);
        close(fd);
        return 1;
    }

    // Save the image to a file
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        free(buffer);
        close(fd);
        return 1;
    }

    fwrite(buffer, 1, bytes_read, fp);
    fclose(fp);

    printf("Image saved to %s\n", IMAGE_FILE);

    // Clean up
    free(buffer);
    close(fd);

    return 0;
}

