#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Timeout duration in seconds
#define TIMEOUT 0.5

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to measure distance using HC-SR04 sensor
float getDistance()
{
    // Trigger the sensor
    gpioTrigger(TRIGGER_PIN, 10, 1);

    // Measure the echo pulse width
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start_tick) / 1000000.0 < TIMEOUT);
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - echo_start) / 1000000.0 < TIMEOUT);
    uint32_t echo_end = gpioTick();

    uint32_t diff = echo_end - echo_start;

    // Calculate the distance in centimeters
    float distance = ((float)diff * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and multiply by 100 to convert m to cm.

    return distance;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Main loop
    while (!terminate)
    {
        // Get the distance from the sensor
        float distance = getDistance();

        // Print the measured distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

