// Function to measure distance using HC-SR04 sensor
float getDistance()
{
    // Trigger the sensor
    gpioTrigger(TRIGGER_PIN, 10, 1);

    // Measure the echo pulse width
    double start_time = time_time();
    while (gpioRead(ECHO_PIN) == 0 && (time_time() - start_time) < TIMEOUT) {}
    double echo_start = time_time();

    while (gpioRead(ECHO_PIN) == 1 && (time_time() - start_time) < TIMEOUT) {}
    double echo_end = time_time();

    double echo_duration = echo_end - echo_start;

    // Calculate the distance in centimeters
    float distance = (echo_duration * SPEED_OF_SOUND) / 2.0;

    return distance;
}

