// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg_addr) {
    int result = ioctl(fd, I2C_SLAVE, 0x68); // MPU6050 address
    if (result < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    char buf[1];
    buf[0] = reg_addr;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return buf[0];
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t value) {
    int result = ioctl(fd, I2C_SLAVE, 0x68); // MPU6050 address
    if (result < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    char buf[2];
    buf[0] = reg_addr;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the MPU6050
int mpu6050_init(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int mpu6050_read_acceleration(int fd, int *accel_x, int *accel_y, int *accel_z) {
    int high_byte, low_byte;

    // Read X axis
    high_byte = i2c_read_reg(fd, ACCEL_XOUT_H);
    low_byte = i2c_read_reg(fd, ACCEL_XOUT_H + 1);

    if (high_byte == -1 || low_byte == -1) {
        fprintf(stderr, "Failed to read X axis acceleration.\n");
        return -1;
    }
    *accel_x = (high_byte << 8) | low_byte;

    // Read Y axis
    high_byte = i2c_read_reg(fd, ACCEL_XOUT_H + 2);
    low_byte = i2c_read_reg(fd, ACCEL_XOUT_H + 3);

    if (high_byte == -1 || low_byte == -1) {
        fprintf(stderr, "Failed to read Y axis acceleration.\n");
        return -1;
    }
    *accel_y = (high_byte << 8) | low_byte;

    // Read Z axis
    high_byte = i2c_read_reg(fd, ACCEL_XOUT_H + 4);
    low_byte = i2c_read_reg(fd, ACCEL_XOUT_H + 5);

    if (high_byte == -1 || low_byte == -1) {
        fprintf(stderr, "Failed to read Z axis acceleration.\n");
        return -1;
    }
    *accel_z = (high_byte << 8) | low_byte;

    return 0;
}

