// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR_1 0x44
#define SHT31_ADDR_2 0x45
#define MEASUREMENT_COMMAND_MSB 0x2C
#define MEASUREMENT_COMMAND_LSB 0x06

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int open_i2c_bus(const char *bus);
int read_sht31(int fd, int address, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
SensorData convert_data(uint8_t data[]);
void print_sensor_data(SensorData data);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nReceived signal %d, cleaning up...\n", signum);
        terminate = 1;
    }
}

// Open I2C bus
int open_i2c_bus(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Read data from SHT31 sensor
int read_sht31(int fd, int address, uint8_t *data) {
    uint8_t command[2] = {MEASUREMENT_COMMAND_MSB, MEASUREMENT_COMMAND_LSB};

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    // Send measurement command
    if (write(fd, command, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(10000); // Wait for measurement (at least 10ms)

    // Read 6 bytes of data
    if (read(fd, data, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Calculate CRC checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int byteCtr = 0; byteCtr < nbrOfBytes; ++byteCtr) {
        crc ^= (data[byteCtr]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^7 + X^5 + X^4 + X^2 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Convert raw data to temperature and humidity
SensorData convert_data(uint8_t data[]) {
    SensorData sensor_data;
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    // Checksum validation
    if (calculate_crc(data, 2, data[2]) != 0 ||
        calculate_crc(data + 3, 2, data[5]) != 0) {
        fprintf(stderr, "Checksum error!\n");
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;
        return sensor_data;
    }

    // Convert to Celsius and percentage relative humidity
    sensor_data.temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)hum_raw / 65535.0;

    return sensor_data;
}

// Print sensor data with timestamp
void print_sensor_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s Temperature: %.2f °C, Humidity: %.2f %%RH\n", buf, data.temperature, data.humidity);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open_i2c_bus(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        SensorData sensor_data;

        // Read from sensor 1
        if (read_sht31(i2c_fd, SHT31_ADDR_1, data) == 0) {
            sensor_data = convert_data(data);
            if (sensor_data.temperature != -999.0) {
                print_sensor_data(sensor_data);
            } else {
                fprintf(stderr, "Invalid data from sensor 1\n");
            }
        } else {
            fprintf(stderr, "Failed to read from sensor 1\n");
        }

        // Read from sensor 2
        if (read_sht31(i2c_fd, SHT31_ADDR_2, data) == 0) {
            sensor_data = convert_data(data);
             if (sensor_data.temperature != -999.0) {
                print_sensor_data(sensor_data);
            } else {
                fprintf(stderr, "Invalid data from sensor 2\n");
            }
        } else {
            fprintf(stderr, "Failed to read from sensor 2\n");
        }

        sleep(5);
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

