#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer = NULL;
    size_t buffer_size;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening device");
        fprintf(stderr, "Device: %s\n", DEVICE_NAME);
        return EXIT_FAILURE;
    }

    // Check if the device supports V4L2
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the image format (YUYV)
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;  // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT failed");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the image buffer
    buffer_size = fmt.fmt.pix.width * fmt.fmt.pix.height * 2; // YUYV is 2 bytes per pixel
    buffer = (unsigned char *)malloc(buffer_size);
    if (!buffer) {
        perror("Failed to allocate buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture the image
    if (read(fd, buffer, buffer_size) != buffer_size) {
        perror("Failed to read frame");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Save the image to a file (simple approach - requires external tools like jpegtran)
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("Failed to open image file for writing");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffer, 1, buffer_size, fp);
    fclose(fp);

    printf("Image saved as %s\n", IMAGE_FILE);

    // Clean up
    free(buffer);
    close(fd);

    return EXIT_SUCCESS;
}

