#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define MAX_DEVICE_ID_LENGTH 20

// Global variable to store the device ID
char device_id[MAX_DEVICE_ID_LENGTH] = {0};

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
