#include <time.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Timeout duration in microseconds
#define TIMEOUT_US 50000 // 50ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to measure distance using HC-SR04 sensor
float getDistance()
{
    long startTime, endTime, pulseWidth;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1.0; // Indicate timeout error
    }
    startTime = time_time();

    // Wait for echo to end (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1.0; // Indicate timeout error
    }
    endTime = time_time();

    // Calculate pulse width in microseconds
    pulseWidth = endTime - startTime;

    // Calculate distance in centimeters
    float distance = (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = getDistance();

        if (distance > 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Sleep for 0.1 seconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");

    return 0;
}

