// Function to read data from DHT22 sensor
int read_dht22_data(float *temperature, float *humidity)
{
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[MAX_TIMINGS];
    int i;

    // Set GPIO pin as output
    gpioSetMode(dht22_gpio, PI_OUTPUT);

    // Send start signal
    gpioWrite(dht22_gpio, 0);
    gpioDelay(1);
    gpioWrite(dht22_gpio, 1);
    gpioDelay(30); // Changed delay to 30 us

    // Set GPIO pin as input
    gpioSetMode(dht22_gpio, PI_INPUT);

    // Read data pulses
    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpioRead(dht22_gpio) == (i % 2)) {
            count++;
            gpioDelay(1); // Delay of 1 us
            if (count > 200) {
                return -1; // Timeout error
            }
        }
        pulse_counts[i] = count;
    }

    // Decode data
    for (i = 2; i < 42; i += 2) {
        long t = pulse_counts[i + 1];

        if ((t > 20) && (t < 70)) {
            data[bit_count / 8] <<= 1;
            if (t > 40) {
                data[bit_count / 8] |= 1;
            }
            bit_count++;
        } else {
          return -1; // Invalid pulse width
        }
    }

    // Validate checksum
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        return -1; // Checksum failure
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0; // Success
}

