// Function to read DHT22 data from a given GPIO pin
int read_dht22_data(int gpio_pin, float *temperature, float *humidity) {
    int data[MAX_TIMINGS] = {0};
    int laststate = PI_HIGH;
    int j = 0;

    // Set GPIO pin as input
    gpioSetMode(gpio_pin, PI_INPUT);

    // Send start signal
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, PI_LOW);
    gpioDelay(1);
    gpioWrite(gpio_pin, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(gpio_pin, PI_INPUT);

    // Read data
    unsigned int loopCnt = 10000;
    while (gpioRead(gpio_pin) == PI_HIGH) {
        if (--loopCnt == 0) return -1; // Timeout
    }

    loopCnt = 10000;
    while (gpioRead(gpio_pin) == PI_LOW) {
        if (--loopCnt == 0) return -1; // Timeout
    }

    loopCnt = 10000;
    while (gpioRead(gpio_pin) == PI_HIGH) {
        if (--loopCnt == 0) return -1; // Timeout
    }

    // Read 40 bits of data
    for (int i = 0; i < MAX_TIMINGS; i++) {
        loopCnt = 10000;
        while (gpioRead(gpio_pin) == PI_LOW) {
            if (--loopCnt == 0) return -1; // Timeout
        }

        long t = time_time();

        loopCnt = 10000;
        while (gpioRead(gpio_pin) == PI_HIGH) {
            if (--loopCnt == 0) return -1; // Timeout
        }

        if ((time_time() - t) > 28) {
            data[j++] = 1;
        } else {
            data[j++] = 0;
        }
    }

    // Validate checksum
    if (j != 40) {
        fprintf(stderr, "Error: Invalid number of data bits received (%d)\n", j);
        return -1;
    }

    int checksum = 0;
    for (int i = 0; i < 8; i++) {
        checksum += data[i];
    }
    for (int i = 8; i < 16; i++) {
        checksum += data[i];
    }
    for (int i = 16; i < 24; i++) {
        checksum += data[i];
    }
    for (int i = 24; i < 32; i++) {
        checksum += data[i];
    }

    int calculated_checksum = 0;
    for (int i = 0; i < 8; i++) {
        calculated_checksum <<= 1;
        calculated_checksum |= data[32 + i];
    }

    if (checksum != calculated_checksum) {
        fprintf(stderr, "Error: Checksum mismatch (received: %d, calculated: %d)\n", checksum, calculated_checksum);
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = 0;
    for (int i = 0; i < 16; i++) {
        *humidity *= 2;
        *humidity += data[i];
    }

    *temperature = 0;
    for (int i = 16; i < 32; i++) {
        *temperature *= 2;
        *temperature += data[i];
    }

    // Handle negative temperatures
    if (*temperature & 0x800) {
        *temperature &= ~0x1000;
        *temperature *= -1;
    }

    return 0;
}

