// Define SPI device path
#define SPI_DEVICE "/dev/spidev0.0"

int main() {
    int spi_fd;
    uint8_t data[4];
    int16_t internal_temp_raw;
    float internal_temp_celsius;
    int16_t thermocouple_temp_raw;
    float thermocouple_temp_celsius;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    // Read data from SPI device
    ssize_t bytes_read = read(spi_fd, data, sizeof(data));
    if (bytes_read != sizeof(data)) {
        perror("Error reading from SPI device");
        fprintf(stderr, "Expected to read 4 bytes, but got %zd\n", bytes_read);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Extract temperature data
    internal_temp_raw = ((data[2] << 8) | data[3]) >> 4;
    thermocouple_temp_raw = ((data[0] << 8) | data[1]);

    // Check for fault conditions
    if (thermocouple_temp_raw & 0x0004) {
        fprintf(stderr, "Thermocouple open circuit!\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (thermocouple_temp_raw & 0x0002) {
        fprintf(stderr, "Thermocouple shorted to GND!\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (thermocouple_temp_raw & 0x0001) {
        fprintf(stderr, "Thermocouple shorted to VCC!\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Convert temperatures to Celsius
    internal_temp_celsius = internal_temp_raw * 0.0625;
    thermocouple_temp_celsius = thermocouple_temp_raw * 0.25;

    // Print results
    printf("Internal Temperature: %.2f °C\n", internal_temp_celsius);
    printf("Thermocouple Temperature: %.2f °C\n", thermocouple_temp_celsius);

    // Close SPI device
    close(spi_fd);

    return EXIT_SUCCESS;
}

