#define TRIG_PIN_1 4
#define ECHO_PIN_1 17
#define TRIG_PIN_2 18
#define ECHO_PIN_2 27

// Speed of sound in cm/s
#define SOUND_SPEED 34300.0

// Timeout duration in seconds
#define TIMEOUT 0.5

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to measure distance from an HC-SR04 sensor
float getDistance(int trigPin, int echoPin)
{
    // Trigger the sensor
    gpioTrigger(trigPin, 10, 1);

    // Measure the pulse width
    uint32_t start_tick = gpioTick();
    while (gpioRead(echoPin) == 0 && (gpioTick() - start_tick) / 1000000.0 < TIMEOUT) {}
    uint32_t echo_start = gpioTick();

    while (gpioRead(echoPin) == 1 && (gpioTick() - echo_start) / 1000000.0 < TIMEOUT) {}
    uint32_t echo_end = gpioTick();

    uint32_t diff = echo_end - echo_start;

    // Calculate the distance in centimeters
    float distance = ((float)diff * SOUND_SPEED) / 2000000.0; // Divide by 1000000.0 to convert us to s, then by 2 for one-way distance

    return distance;
}

