    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_write_byte(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1; //0b00100111

    // Set filter coefficient to 4 and standby time to 0.5ms
    if (i2c_write_byte(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1; //0b10100000

    return 0;
}

