#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

/* Global variable to indicate program termination */
volatile sig_atomic_t terminate = 0;

/* Signal handler function */
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main()
{
    int rc;
    int current_state = 0;

    /* Register signal handlers */
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin as output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    /* Main loop */
    while (!terminate) {
        /* Toggle the GPIO state */
        current_state = !current_state;
        gpioWrite(GPIO_PIN, current_state);

        /* Print the current state */
        printf("GPIO %d set to %s\n", GPIO_PIN, current_state ? "HIGH" : "LOW");

        /* Wait for 1 second */
        sleep(1);
    }

    /* Release GPIO resource before exiting */
    gpioTerminate();

    return EXIT_SUCCESS;
}

