#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B9600

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        keep_running = 0;
    }
}

int main() {
    int uart_fd;
    struct termios tty;
    char read_buf[256];
    ssize_t num_read;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open UART port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART port");
        return EXIT_FAILURE;
    }

    // Configure UART settings
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8N1, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // Timeout of 0.5 seconds

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART communication started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        memset(read_buf, 0, sizeof(read_buf)); // Clear the buffer before reading
        num_read = read(uart_fd, read_buf, sizeof(read_buf) - 1);

        if (num_read > 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the received data with a timestamp
            printf("[%s] Received: %s\n", timestamp, read_buf);
        } else if (num_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available within timeout, continue looping
                usleep(100000); // Sleep for 0.1 seconds
            } else {
                perror("Error reading from UART");
                break; // Exit loop on other read errors
            }
        } else {
            // End-of-file condition or no data received
            usleep(100000); // Sleep for 0.1 seconds
        }
    }

    // Close UART port
    if (close(uart_fd) == -1) {
        perror("Error closing UART port");
    }

    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

