// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Timeout duration in microseconds
#define TIMEOUT_US 20000 // 20ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to measure distance using HC-SR04 sensor
float getDistance()
{
    long startTime, endTime, pulseWidth;

    // Trigger the sensor
    gpioTrigger(TRIGGER_PIN, 10, 1);

    // Wait for the echo pin to go high (start of pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout error
    }
    startTime = gpioTick();

    // Wait for the echo pin to go low (end of pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }
    endTime = gpioTick();

    // Calculate the pulse width in microseconds
    pulseWidth = endTime - startTime;

    // Check for invalid pulse widths
    if (pulseWidth <= 0 || pulseWidth > 20000) // Reasonable range: 0-20ms
    {
        fprintf(stderr, "Invalid pulse width: %ld us\n", pulseWidth);
        return -1.0; // Indicate invalid reading
    }

    // Calculate the distance in centimeters
    float distance = (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and multiply by 100 to get cm.

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = getDistance();

        if (distance >= 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        time_sleep(0.5); // Delay for 0.5 seconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated successfully.\n");

    return 0;
}

