// Function to generate a 10us pulse on the trigger pin
void trigger_pulse(int pin) {
    gpioWrite(pin, 1); // Set trigger HIGH
    gpioDelay(10);      // Wait for 10 microseconds
    gpioWrite(pin, 0); // Set trigger LOW
}

// Function to measure the duration of the echo pulse and calculate distance
float get_distance() {
    long start_tick, end_tick;

    // Trigger the sensor
    trigger_pulse(TRIGGER_PIN);

    // Measure the echo pulse width
    int timeout = 50000; // Timeout after 50ms
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    timeout = 50000; // Reset timeout for echo end
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1);
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    // Calculate the pulse duration in seconds
    double pulse_duration = (double)(end_tick - start_tick) / 1000000.0;

    // Calculate the distance in centimeters (speed of sound: 343 m/s)
    // Distance = (Time * Speed of Sound) / 2
    // Distance = (pulse_duration * 34300) / 2
    float distance = (pulse_duration * 34300.0) / 2.0;

    return distance;
}

