#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ENABLE      0x80
#define TCS34725_ATIME       0x81
#define TCS34725_CONTROL     0x8F
#define TCS34725_CDATA       0x90
#define TCS34725_RDATA       0x92
#define TCS34725_GDATA       0x94
#define TCS34725_BDATA       0x96

// Enable Register Values
#define TCS34725_PON         0x01
#define TCS34725_AEN         0x02

// Integration Time Value
#define TCS34725_INTEGRATIONTIME_2_4MS  0xFF   //  2.4ms - 1 cycle    - Max Count: 1024

// Gain Value
#define TCS34725_GAIN_60X            0x03   // 60x gain

int i2c_fd;
volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int tcs34725_init() {
    uint8_t buf[2];

    // Enable power and ALS
    buf[0] = TCS34725_ENABLE;
    buf[1] = TCS34725_PON | TCS34725_AEN;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write enable register");
        return -1;
    }

    // Set integration time
    buf[0] = TCS34725_ATIME;
    buf[1] = TCS34725_INTEGRATIONTIME_2_4MS;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write ATIME register");
        return -1;
    }

    // Set gain
    buf[0] = TCS34725_CONTROL;
    buf[1] = TCS34725_GAIN_60X;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write CONTROL register");
        return -1;
    }

    return 0;
}

int read_raw_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[1];
    uint8_t data[8];

    // Read clear channel
    buf[0] = TCS34725_CDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write CDATA register address");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read clear data");
        return -1;
    }
    *clear = (data[1] << 8) | data[0];

    // Read red channel
    buf[0] = TCS34725_RDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write RDATA register address");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read red data");
        return -1;
    }
    *red = (data[1] << 8) | data[0];

    // Read green channel
    buf[0] = TCS34725_GDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write GDATA register address");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read green data");
        return -1;
    }
    *green = (data[1] << 8) | data[0];

    // Read blue channel
    buf[0] = TCS34725_BDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write BDATA register address");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read blue data");
        return -1;
    }
    *blue = (data[1] << 8) | data[0];

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    int address = 0x29;
    uint16_t clear, red, green, blue;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    while (keep_running) {
        // Read raw data
        if (read_raw_data(&clear, &red, &green, &blue) == 0) {
            // Print raw values
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(0.5);
    }

    // Disable sensor before exiting
    uint8_t disable_buf[2];
    disable_buf[0] = TCS34725_ENABLE;
    disable_buf[1] = 0x00; // Power off and ALS disable
    if (write(i2c_fd, disable_buf, 2) != 2) {
        perror("Failed to write disable command");
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

