#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>
#include <time.h>

// Configuration
#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B9600
#define READ_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        keep_running = 0;
    }
}

int main() {
    int uart_fd;
    struct termios tty;
    char read_buffer[256];
    ssize_t num_read;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open UART port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART port");
        return EXIT_FAILURE;
    }

    // Configure UART settings
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8N1, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 1;                             // Wait for up to 0.1 second

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART communication started on %s at %d baud.\n", UART_PORT, BAUD_RATE);

    while (keep_running) {
        memset(read_buffer, 0, sizeof(read_buffer)); // Clear buffer before reading
        num_read = read(uart_fd, read_buffer, sizeof(read_buffer) - 1);

        if (num_read > 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print timestamped data
            printf("[%s] Received: %s\n", timestamp, read_buffer);
        } else if (num_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, but no error
                usleep(READ_INTERVAL_MS * 1000); // Sleep for the interval
            } else {
                perror("Error reading from UART");
                break; // Exit loop on read error
            }
        } else {
            // End of file or zero bytes read (should not happen normally)
            printf("EOF or zero bytes read.\n");
            break;
        }

        usleep(READ_INTERVAL_MS * 1000); // Sleep for the interval
    }

    // Close UART port
    if (close(uart_fd) == -1) {
        perror("Error closing UART port");
    }

    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

