    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Trigger the sensor
        gpioTrigger(TRIGGER_PIN, 10, 1); // 10 us trigger pulse

        // Measure echo pulse width with timeout
        double start_time = time_time();
        int timeout_occurred = 0;
        while (gpioRead(ECHO_PIN) == 0 && !timeout_occurred)
        {
            if ((time_time() - start_time) > TIMEOUT)
            {
                timeout_occurred = 1;
                break;
            }
        }

        if (timeout_occurred)
        {
            fprintf(stderr, "Timeout occurred waiting for echo.\n");
            continue; // Skip to the next iteration
        }

        double echo_start = time_time();

        while (gpioRead(ECHO_PIN) == 1 && !timeout_occurred)
        {
            if ((time_time() - start_time) > TIMEOUT)
            {
                timeout_occurred = 1;
                break;
            }
        }

        if (timeout_occurred)
        {
            fprintf(stderr, "Timeout occurred waiting for echo end.\n");
            continue; // Skip to the next iteration
        }

        double echo_end = time_time();

        // Calculate distance in centimeters
        double pulse_duration = echo_end - echo_start;
        double distance = (pulse_duration * SPEED_OF_SOUND) / 2.0;

        // Print the calculated distance
        printf("Distance: %.2f cm\n", distance);

